--[[
* allrecipes
*
* Every era synthesis and desynthesis recipe on Phoenix, by craft. Pick one to see its materials,
* your odds (success, HQ, skill-up) at your craft levels, and what it makes you: type in AH prices
* and it works out the profit a try, selling on the AH or to an NPC. Prices are kept and shared by
* every recipe and character. Ctrl+click any item to open it on ffxiah.com.
*
* The recipes come from data/recipes.lua, generated by tools/gen_recipes.py from Phoenix's own
* recipe table, and the odds are worked out the way Phoenix does (odds.lua). Recipes from Abyssea
* on aren't included; RoZ, CoP, ToAU and WotG ones are marked and can be hidden.
*
* When you look at an item's price history at the auction house, it's kept (ahhistory.lua) and
* used for any price you haven't typed in.
*
* Nothing is ever sent to the server and nothing is asked of it: allrecipes only reads client
* memory and the packets the game receives anyway.
--]]

addon.name    = 'allrecipes';
addon.author  = 'Relli';
addon.version = '0.2';
addon.desc    = 'Every era recipe by craft, with your odds, skill-ups, HQ rates and profit.';
addon.link    = '';

require('common');
local chat     = require('chat');
local settings = require('settings');
local model    = require('model');
local player   = require('player');
local prices   = require('prices');
local ui       = require('ui');
local ah       = require('ahhistory');
local tray     = require('tray');

local defaults = T{
    visible    = false,
    minimized  = false,   -- shown as an icon at the bottom right instead
    x = 120, y = 120, w = 900, h = 560,
    craft      = 1,       -- the tab: 1 woodworking .. 8 cooking
    desynth    = false,
    skillups   = false,   -- only recipes that can raise the craft
    sell       = 'AH',    -- what the profit assumes: 'AH' or 'NPC'
    expansions = T{ ROTZ = true, COP = true, TOAU = true, WOTG = false },
    sub        = true,    -- list recipes where the craft is only a sub-craft
    keyitems   = true,    -- list recipes that need a key item
    gear       = T{ 0, 0, 0, 0, 0, 0, 0, 0 },  -- skill added by gear or moghancements, by craft
    sort       = 'lv',
    dir        = 1,
    search     = '',
    selected   = 0,       -- the recipe shown
    cfg        = false,   -- the settings window is open
    theme      = 'clean', -- 'clean' (scouter's), 'guild' or 'vanadiel'
    ahread     = true,    -- keep the AH price history of what you look at
    ahbasis    = 'single',-- where an item has both, its AH price comes from 'single' or 'stack' sales
};

local ar = { settings = nil };

local function msg(text)
    print(chat.header(addon.name):append(chat.message(text)));
end

local function err(text)
    print(chat.header(addon.name):append(chat.error(text)));
end

local function save()
    settings.save();
end

local CRAFT_NAMES = {
    wood = 1, woodworking = 1, smith = 2, smithing = 2, gold = 3, goldsmithing = 3, cloth = 4, clothcraft = 4,
    leather = 5, leathercraft = 5, bone = 6, bonecraft = 6, alchemy = 7, alch = 7, cook = 8, cooking = 8,
};

local function help()
    msg('/allrecipes (or /ar)   show or hide the window, or bring it back from its icon');
    msg('/ar <craft>   open it on a craft: wood, smith, gold, cloth, leather, bone, alchemy, cook');
    msg('/ar min   minimize it to an icon at the bottom right; click the icon to bring it back');
    msg('/ar prices export [file]   save your prices as JSON (in config/addons/allrecipes)');
    msg('/ar prices import <file>   add prices from JSON: {"4098": 90} or [{"id": 4098, "price": 90}]');
    msg('/ar reset   move the window back to where it starts');
    msg('/ar ah   whether AH price history is being kept, and how much');
    msg('/ar ah on|off   keep the AH price history of what you look at (only read, never asked for)');
    msg('/ar ah scan   look for it in memory now, with a price history open at the auction house');
    msg('/ar debug   your craft levels as the addon reads them');
end

local function debug()
    local you = player.you(ar.settings.gear);
    for c, craft in ipairs(player.CRAFTS) do
        local im = player.imagery[c];
        msg(('%s: level %d, rank %d (%s), %s%s'):fmt(craft.name, you.level[c], you.rank[c], player.RANKS[you.rank[c]] or '?',
            you.capped[c] and 'capped' or 'not capped', im and (', image support +%d'):fmt(im.power) or ''));
    end
    local n, synth = 0, 0;
    for _, r in ipairs(model.recipes or { }) do
        n = n + 1;
        synth = synth + (r[2] == 0 and 1 or 0);
    end
    local priced = 0;
    for _ in pairs(prices.list) do
        priced = priced + 1;
    end
    msg(('%d recipes (%d synthesis, %d desynthesis); %d prices typed in'):fmt(n, synth, n - synth, priced));
    msg(tray.status());
end

ashita.events.register('load', 'allrecipes_load', function ()
    ar.settings = settings.load(defaults);
    tray.init('allrecipes');
    ui.search[1] = ar.settings.search or '';
    if (not model.load()) then
        err(('No recipe data (%s). Run tools/gen_recipes.py.'):fmt(tostring(model.error)));
    end
    prices.load();
    if (prices.error ~= nil) then
        err(('Couldn\'t read your prices (%s).'):fmt(prices.error));
    end
    prices.estimate = ah.estimate;
    ah.stacks = model.error == nil and model.stacks or nil;
    ah.load();
    if (ah.error ~= nil) then
        err(('Couldn\'t read the AH history (%s).'):fmt(ah.error));
    end
end);

settings.register('settings', 'allrecipes_settings_update', function (s)
    if (s ~= nil) then
        ar.settings = s;
        ui.search[1] = s.search or '';
    end
end);

ashita.events.register('unload', 'allrecipes_unload', function ()
    tray.hide('allrecipes');
    settings.save();
    if (prices.dirty) then
        prices.save();
    end
    if (ah.dirty) then
        ah.save();
    end
end);

ashita.events.register('command', 'allrecipes_command', function (e)
    local args = e.command:args();
    if (#args == 0 or (args[1]:lower() ~= '/allrecipes' and args[1]:lower() ~= '/ar')) then
        return;
    end
    e.blocked = true;
    local s = ar.settings;
    local what = (args[2] or ''):lower();
    if (what == '') then
        if (s.visible and s.minimized) then
            s.minimized = false;
        else
            s.visible = not s.visible;
        end
        save();
    elseif (what == 'min' or what == 'minimize') then
        s.visible, s.minimized = true, true;
        save();
    elseif (CRAFT_NAMES[what] ~= nil) then
        s.visible, s.minimized, s.craft = true, false, CRAFT_NAMES[what];
        ui.scroll_top = true;
        save();
    elseif (what == 'prices' and (args[3] or ''):lower() == 'export') then
        local name = args[4] or 'prices.json';
        local n, why = prices.export(name);
        if (n == nil) then
            err(why);
        else
            msg(('Saved %d prices to %s.'):fmt(n, prices.path(name)));
        end
    elseif (what == 'prices' and (args[3] or ''):lower() == 'import' and args[4] ~= nil) then
        local added, changed, skipped = prices.import(args[4]);
        if (added == nil) then
            err(('Couldn\'t import prices: %s.'):fmt(changed));
        else
            msg(('Imported prices: %d new, %d changed%s.'):fmt(added, changed, skipped > 0 and (', %d skipped'):fmt(skipped) or ''));
        end
    elseif (what == 'reset') then
        s.x, s.y, s.w, s.h, ui.reset = defaults.x, defaults.y, defaults.w, defaults.h, true;
        save();
        msg('Window moved back to where it starts.');
    elseif (what == 'ah') then
        local sub = (args[3] or ''):lower();
        if (sub == 'on' or sub == 'off') then
            s.ahread = sub == 'on';
            save();
            msg(('Keeping AH price history %s.'):fmt(s.ahread and 'on' or 'off'));
        elseif (sub == 'scan') then
            local n = ah.scan();
            if (n > 0) then
                ah.arm(os.clock());
                msg(('Found the price history in %d place%s; watching it.'):fmt(n, n == 1 and '' or 's'));
            else
                err(ah.error ~= nil and ('Couldn\'t look: %s.'):fmt(ah.error)
                    or 'No price history in memory. Open an item\'s price history at the auction house first.');
            end
        else
            local last = ah.last;
            msg(('AH price history %s: %d items kept.'):fmt(s.ahread and 'on' or 'off', ah.count()));
            msg(('%s; %d place%s watched, %d look%s through memory this visit.'):fmt(
                os.clock() < ah.armed and 'At the auction house' or 'Not at the auction house',
                #ah.spots, #ah.spots == 1 and '' or 's', ah.scans, ah.scans == 1 and '' or 's'));
            if (last ~= nil) then
                msg(('Last kept: %s, %d sales (%s).'):fmt(model.name(last.id), last.n,
                    last.kind == 'unknown' and 'singles or stacks unknown' or last.kind .. 's'));
            end
        end
    elseif (what == 'debug') then
        debug();
    else
        help();
    end
end);

-- The auction house opened (the server's 0x04C): watch for price histories. Only read.
ashita.events.register('packet_in', 'allrecipes_packet_in', function (e)
    if (e.id == 0x04C) then
        ah.arm(os.clock());
    end
end);

ashita.events.register('d3d_present', 'allrecipes_present', function ()
    local now = os.clock();
    player.update(now);
    prices.tick(now);
    local s = ar.settings;
    if (s == nil) then
        return;
    end
    ah.enabled = s.ahread;
    if (ah.prefer ~= s.ahbasis) then
        ah.prefer = s.ahbasis == 'stack' and 'stack' or 'single';
        prices.touch();
    end
    ah.tick(now);
    if (s.visible and s.minimized) then
        ui.draw_icon(s, save);
        return;
    end
    tray.hide('allrecipes');
    if (s.visible) then
        ui.draw(s, player.you(s.gear), save);
    end
end);
